-- NovaMarket comprehensive demo seed
-- Common demo password hash is shared across seeded accounts.
-- Run this after database/schema.sql, or use database/setup_demo.sql to rebuild schema and data together.
SET @OLD_SQL_SAFE_UPDATES := @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;









-- Keep dedicated galleries for the original 10 media-backed products.

-- Products 11-32 do not have dedicated cloud images in the demo bundle yet.
-- Remove the recycled cross-product photos so those products fall back cleanly
-- until their own media is uploaded through the admin or seller product editor.
DELETE FROM product_media WHERE product_id BETWEEN 11 AND 32;
UPDATE products SET image_url = NULL WHERE id BETWEEN 11 AND 32;












-- Sequential reviewer customer accounts with matching delivered orders.

-- Delivered review-support orders that make every seeded review trace back to a purchase.



    product_id,
    user_id,
    rating,
    title,
    comment,
    is_visible,
    is_flagged,
    created_at,
    updated_at
) VALUES
    (1, 9, 5, 'A really polished product', 'The quality feels better than the price suggests. After using it for commutes and focus sessions, I can say the sound profile is noticeable, the charging case feels refined, and the fit holds up nicely.', 1, 0, '2026-02-01 23:00:00', '2026-02-01 23:00:00'),
    (1, 10, 5, 'Would happily buy this again', 'I was hoping the Nova Wireless Earbuds would feel dependable for commutes and focus sessions, and it does. The sound profile works as described, the charging case is genuinely useful, and the fit gives it a polished finish.', 1, 0, '2026-02-02 02:00:00', '2026-02-02 02:00:00'),
