SELECT id, 'photo', 'https://storage.googleapis.com/novamarket-product-images/product-images/nova-wireless-earbuds-2.jpg'
FROM product_reviews
WHERE product_id = 1
ORDER BY id
LIMIT 1;

SELECT id, 'photo', 'https://storage.googleapis.com/novamarket-product-images/product-images/solace-aroma-diffuser-2.jpg'
FROM product_reviews
WHERE product_id = 5
ORDER BY id
LIMIT 1;

SELECT id, 'photo', 'https://storage.googleapis.com/novamarket-product-images/product-images/terra-recycled-tote-2.jpg'
FROM product_reviews
WHERE product_id = 10
ORDER BY id
LIMIT 1;

SELECT id, 'photo', 'https://storage.googleapis.com/novamarket-product-images/product-images/solace-aroma-diffuser.jpg'
FROM product_reviews
WHERE product_id = 30
ORDER BY id
LIMIT 1;

SELECT id, 1, 'Contains repetitive spam wording for moderation testing.'
FROM product_reviews
WHERE product_id = 14
ORDER BY id
LIMIT 1;

SELECT id, 1, 'Flagged by admin as a moderation workflow example.'
FROM product_reviews
WHERE product_id = 27
ORDER BY id
LIMIT 1;

UPDATE product_reviews pr
INNER JOIN product_review_flags pf ON pf.review_id = pr.id
SET pr.is_flagged = 1,
    pr.flagged_reason = pf.reason,
    pr.moderated_by = 1;

UPDATE products p
LEFT JOIN (
    SELECT
        product_id,
        ROUND(AVG(rating), 2) AS average_rating,
        COUNT(*) AS review_count
    FROM product_reviews
    WHERE is_visible = 1
    GROUP BY product_id
) review_stats
    ON review_stats.product_id = p.id
SET p.average_rating = COALESCE(review_stats.average_rating, 0),
    p.review_count = COALESCE(review_stats.review_count, 0);

SET SQL_SAFE_UPDATES = @OLD_SQL_SAFE_UPDATES;
