    (2, 'Deals & Promotions', 'deals-rewards', 'Promo codes, coupons, and campaign offers.', 'tag', 2),
    (3, 'Checkout & Cart', 'checkout-cart', 'Cart changes, address checks, and checkout issues.', 'document', 3),
    (4, 'Orders & Shipping', 'orders-shipping', 'Order tracking, delivery timing, and address edits.', 'truck', 4),
