    (8, 'Policies', 'policies', 'Marketplace rules and general policy questions.', 'notice', 8);
INSERT INTO help_questions (id, category_id, question, answer, is_hot, sort_order) VALUES
    (1, 6, 'How do I reset my account password?', 'Use the sign in page password recovery option and follow the reset link sent to your email. If the message does not arrive, check spam and confirm you entered the same email registered on your NovaMarket account.', 1, 1),
    (2, 6, 'Why does my sign in keep failing?', 'Login can fail when the password is wrong, the account is inactive, or repeated attempts triggered a temporary rate limit. Wait a few minutes, then retry with the exact email used during registration.', 1, 2),
    (3, 3, 'Why is my cart not updating?', 'Cart updates can fail if the session expires, stock changes in the background, or the browser is still showing cached data. Refresh the page and try again from the latest cart view.', 1, 3),
    (4, 3, 'How do I apply a coupon at checkout?', 'Choose the coupon from the checkout page before continuing to Stripe. Discounts only apply when the order meets the campaign rules such as minimum spend or seller eligibility.', 1, 4),
    (5, 4, 'Where can I track my package?', 'Open your order history and look inside the seller package card. Tracking numbers, courier names, and estimated delivery dates are shown there once the seller updates the shipment.', 1, 5),
    (6, 5, 'How do I request a return or refund?', 'Open a delivered order package from your order history, choose Return / refund, pick the reason, and submit the request. Sellers or admins can then review and respond to it.', 1, 6),
    (7, 5, 'When will my refund be completed?', 'Refund timing depends on the seller action and your payment provider. Once a request is marked refunded in NovaMarket, your bank or card provider may still need several business days to reflect it.', 1, 7),
    (8, 7, 'How do sellers update delivery status?', 'Sellers can open a delivery package in the seller workspace and update the courier, tracking number, delivery date, and package status from one page.', 1, 8),
    (9, 7, 'Why can’t I publish my store yet?', 'Some stores remain pending until profile information is complete or an admin review is finished. Check your seller profile and orders dashboard for the latest status.', 0, 9),
    (10, 1, 'Can I shop from multiple sellers in one order?', 'Yes. NovaMarket groups products by seller inside a single checkout, and each seller package can move through its own delivery timeline after the order is paid.', 0, 10),
    (11, 1, 'Do products include review details?', 'Product pages display average rating, review count, and review content when available. Reviews are tied to real seeded product review rows in this demo database.', 0, 11),
    (12, 2, 'Are promotions available all year?', 'No. Some coupons are limited to campaign dates, selected sellers, or minimum spend thresholds. Always check the title and expiry window before using a code.', 0, 12),
    (13, 4, 'Can I change the shipping address after ordering?', 'Address changes depend on the package status. If the seller has not yet shipped the order, contact support or the seller chat as soon as possible.', 0, 13),
    (14, 8, 'What items are not eligible for return?', 'Used personal-care goods, custom items, and products marked non-returnable are typically excluded unless they arrive damaged, incomplete, or incorrect.', 0, 14),
    (15, 8, 'Who handles payment processing?', 'Stripe handles payment processing for checkout. NovaMarket stores order details and shipping records, while payment confirmation is returned by Stripe webhooks.', 0, 15),
    (16, 2, 'Why does a coupon show but not apply?', 'A coupon may be inactive, expired, linked to a different seller, or below the required spend threshold. Review the coupon card and the order summary before submitting checkout.', 0, 16);
