    (3, 'SHIPFREE60', 'Free shipping threshold', 'Unlock free shipping once your basket reaches the minimum spend.', 'free_shipping', 'shipping', 0.00, 60.00, NULL, '2026-03-15 00:00:00', '2026-04-30 23:59:59', 1, 1),
    (4, 'HARBOR10', 'Harbor Home comfort edit', 'Take 10% off selected comfort picks from Harbor Home.', 'shop', 'percentage', 10.00, 50.00, 4, '2026-03-18 00:00:00', '2026-04-18 23:59:59', 1, 1),
    (5, 'NORTHWIND8', 'Northwind audio perk', 'Fixed savings on selected desk audio and travel-friendly tech.', 'shop', 'fixed_amount', 8.00, 70.00, 2, '2026-03-22 00:00:00', '2026-04-20 23:59:59', 0, 1),
    (6, 'SUMMIT18', 'Summit Office workspace deal', 'Upgrade your desk setup with a fixed discount from Summit Office.', 'shop', 'fixed_amount', 18.00, 120.00, 3, '2026-03-16 00:00:00', '2026-04-15 23:59:59', 0, 1),
    (7, 'CEDARSHIP', 'Cedar Kitchen delivery perk', 'Free shipping on qualifying kitchen orders from Cedar Kitchen.', 'free_shipping', 'shipping', 0.00, 40.00, 6, '2026-03-21 00:00:00', '2026-04-25 23:59:59', 0, 1),
    (8, 'WELLNESS12', 'Studio Well calm routine', 'Save 12% on selected wellness bundles.', 'shop', 'percentage', 12.00, 45.00, 7, '2026-03-22 00:00:00', '2026-04-21 23:59:59', 1, 1),
    (9, 'ATLAS15', 'Atlas Travelworks launch offer', 'Get a fixed discount on organizers, bags, and travel storage.', 'shop', 'fixed_amount', 15.00, 90.00, 8, '2026-03-25 00:00:00', '2026-04-30 23:59:59', 0, 1),
