    (1, 2, 1, 'NM-TECH-001', 'Nova Wireless Earbuds', 'nova-wireless-earbuds', 'Noise-controlled earbuds with a pocket-size charging case.', 'Nova Wireless Earbuds are tuned for commuting and study sessions, with balanced sound, touch controls, and a secure in-ear fit.', 79.90, 99.90, 24, 'https://storage.googleapis.com/novamarket-product-images/product-images/nova-wireless-earbuds-1.jpg', 0.00, 0, 1, 1, '2026-02-02 10:15:00'),
    (2, 3, 6, 'NM-DESK-001', 'Echo Mechanical Keyboard', 'echo-mechanical-keyboard', 'Compact tactile keyboard with hot-swappable switches.', 'Echo Mechanical Keyboard is built for long typing sessions, with sound-dampened keys, USB-C connectivity, and adjustable tilt.', 119.00, NULL, 12, 'https://storage.googleapis.com/novamarket-product-images/product-images/echo-mechanical-keyboard-1.jpg', 0.00, 0, 1, 1, '2026-01-20 09:45:00'),
    (3, 3, 6, 'NM-DESK-002', 'Halo Standing Desk Lamp', 'halo-standing-desk-lamp', 'Adjustable LED lamp with warm-to-cool light presets.', 'Halo Standing Desk Lamp offers glare-free lighting, a compact footprint, and four brightness zones for home office setups.', 64.50, 84.50, 16, 'https://storage.googleapis.com/novamarket-product-images/product-images/halo-standing-desk-lamp-1.jpg', 0.00, 0, 1, 0, '2026-01-15 16:30:00'),
    (4, 6, 3, 'NM-KITCHEN-001', 'Ember Mug Warmer', 'ember-mug-warmer', 'Desk-friendly warmer that keeps coffee and tea at serving temperature.', 'Ember Mug Warmer uses low-profile heating with a splash-safe surface and one-button controls for shared workspaces.', 42.90, NULL, 31, 'https://storage.googleapis.com/novamarket-product-images/product-images/ember-mug-warmer-1.jpg', 0.00, 0, 1, 0, '2026-02-10 08:10:00'),
    (5, 7, 4, 'NM-WELL-001', 'Solace Aroma Diffuser', 'solace-aroma-diffuser', 'Ceramic diffuser with quiet mist modes and timer presets.', 'Solace Aroma Diffuser brings a subtle mist output, soft ambient light, and auto shutoff for evening routines.', 58.00, 72.00, 9, 'https://storage.googleapis.com/novamarket-product-images/product-images/solace-aroma-diffuser-1.jpg', 0.00, 0, 1, 1, '2026-02-24 12:00:00'),
    (6, 8, 7, 'NM-TRAVEL-001', 'TideFold Weekender Bag', 'tidefold-weekender-bag', 'Water-resistant carry bag sized for short trips and day use.', 'TideFold Weekender Bag includes a padded laptop sleeve, trolley strap, and separate shoe compartment.', 89.00, 110.00, 7, 'https://storage.googleapis.com/novamarket-product-images/product-images/tidefold-weekender-bag-1.jpg', 0.00, 0, 1, 0, '2026-01-08 14:20:00'),
    (7, 7, 4, 'NM-WELL-002', 'Pulse Smart Bottle', 'pulse-smart-bottle', 'Insulated bottle with hydration reminders and a carry loop.', 'Pulse Smart Bottle tracks your refill routine, keeps drinks cool, and charges with a hidden USB-C port.', 54.00, NULL, 18, 'https://storage.googleapis.com/novamarket-product-images/product-images/pulse-smart-bottle-1.jpg', 0.00, 0, 1, 0, '2026-02-12 11:15:00'),
    (8, 4, 2, 'NM-HOME-001', 'Hearth Throw Blanket', 'hearth-throw-blanket', 'Soft woven blanket for lounge corners and reading nooks.', 'Hearth Throw Blanket uses a textured weave and machine-washable fibers for everyday living spaces.', 49.00, 65.00, 20, 'https://storage.googleapis.com/novamarket-product-images/product-images/hearth-throw-blanket-1.jpg', 0.00, 0, 1, 0, '2026-02-18 15:10:00'),
    (9, 6, 3, 'NM-KITCHEN-002', 'AeroBlend Portable Blender', 'aeroblend-portable-blender', 'Rechargeable smoothie blender for desks, dorms, and travel.', 'AeroBlend Portable Blender crushes soft fruit and ice, detaches for washing, and stores neatly in a drawer.', 68.00, 82.00, 14, 'https://storage.googleapis.com/novamarket-product-images/product-images/aeroblend-portable-blender-1.jpg', 0.00, 0, 1, 1, '2026-02-05 13:35:00'),
    (10, 5, 5, 'NM-LIFE-001', 'Terra Recycled Tote', 'terra-recycled-tote', 'Structured everyday tote made from recycled canvas.', 'Terra Recycled Tote includes an interior bottle pocket, magnetic top closure, and reinforced handles.', 36.00, NULL, 26, 'https://storage.googleapis.com/novamarket-product-images/product-images/terra-recycled-tote-1.jpg', 0.00, 0, 1, 0, '2026-01-29 17:05:00'),
    (11, 2, 1, 'NM-TECH-002', 'Orbit USB-C Hub', 'orbit-usbc-hub', 'Slim USB-C hub with HDMI, USB-A, and power pass-through.', 'Orbit USB-C Hub adds the essential desk ports you need without cluttering your bag or workstation.', 49.00, 59.00, 29, 'https://storage.googleapis.com/novamarket-product-images/product-images/echo-mechanical-keyboard-2.jpg', 0.00, 0, 1, 0, '2026-02-07 09:10:00'),
