    (13, 3, 6, 'NM-DESK-004', 'Linen Desk Pad', 'linen-desk-pad', 'Soft-touch desk pad that adds texture and protects surfaces.', 'Linen Desk Pad creates a softer workspace with enough grip for keyboards, notebooks, and daily accessories.', 28.00, 36.00, 40, 'https://storage.googleapis.com/novamarket-product-images/product-images/echo-mechanical-keyboard-3.jpg', 0.00, 0, 1, 0, '2026-02-13 14:25:00'),
    (14, 4, 2, 'NM-HOME-002', 'Arc Seat Cushion', 'arc-seat-cushion', 'Supportive seat cushion for dining chairs, benches, and work nooks.', 'Arc Seat Cushion adds everyday comfort with a structured foam core and removable woven cover.', 39.00, 49.00, 28, 'https://storage.googleapis.com/novamarket-product-images/product-images/hearth-throw-blanket-2.jpg', 0.00, 0, 1, 0, '2026-02-11 16:05:00'),
    (15, 6, 3, 'NM-KITCHEN-003', 'BrewMate Pour Over Kettle', 'brewmate-pour-over-kettle', 'Gooseneck kettle designed for controlled pours and small kitchens.', 'BrewMate Pour Over Kettle balances a precise spout with a compact footprint for daily coffee routines.', 55.00, 68.00, 17, 'https://storage.googleapis.com/novamarket-product-images/product-images/aeroblend-portable-blender-2.jpg', 0.00, 0, 1, 0, '2026-02-14 09:00:00'),
    (16, 6, 3, 'NM-KITCHEN-004', 'Drift Ceramic Storage Jars', 'drift-ceramic-storage-jars', 'Set of ceramic jars for tea, coffee, grains, or counter display.', 'Drift Ceramic Storage Jars bring neat organization and a warm matte finish to compact kitchen shelves.', 47.00, 58.00, 19, 'https://storage.googleapis.com/novamarket-product-images/product-images/ember-mug-warmer-2.jpg', 0.00, 0, 1, 0, '2026-02-16 13:15:00'),
