    (18, 7, 4, 'NM-WELL-003', 'Nourish Glass Tea Bottle', 'nourish-glass-tea-bottle', 'Infuser bottle for tea, fruit water, and workday hydration.', 'Nourish Glass Tea Bottle makes simple infusion routines easy with a leak-resistant lid and removable basket.', 34.00, 42.00, 27, 'https://storage.googleapis.com/novamarket-product-images/product-images/pulse-smart-bottle-2.jpg', 0.00, 0, 1, 0, '2026-02-19 08:40:00'),
