    (20, 5, 5, 'NM-LIFE-002', 'Porter Tech Pouch', 'porter-tech-pouch', 'Structured organizer for cables, chargers, and pocket tools.', 'Porter Tech Pouch keeps the little things together, whether you are commuting, traveling, or hot-desking.', 31.00, 39.00, 36, 'https://storage.googleapis.com/novamarket-product-images/product-images/terra-recycled-tote-2.jpg', 0.00, 0, 1, 0, '2026-02-20 10:30:00'),
    (21, 3, 6, 'NM-DESK-005', 'Studio Monitor Light Bar', 'studio-monitor-light-bar', 'USB-powered monitor light bar with dimmable desk lighting.', 'Studio Monitor Light Bar brightens the keyboard area without taking up precious space on the desk.', 88.00, 109.00, 18, 'https://storage.googleapis.com/novamarket-product-images/product-images/halo-standing-desk-lamp-3.jpg', 0.00, 0, 1, 1, '2026-02-22 17:00:00'),
    (22, 4, 4, 'NM-WELL-004', 'Haven Reed Diffuser Set', 'haven-reed-diffuser-set', 'Long-lasting diffuser set with a clean, soft home fragrance.', 'Haven Reed Diffuser Set adds gentle fragrance to bedrooms and lounge spaces with a low-maintenance design.', 46.00, 57.00, 25, 'https://storage.googleapis.com/novamarket-product-images/product-images/solace-aroma-diffuser-3.jpg', 0.00, 0, 1, 0, '2026-02-23 09:20:00'),
    (23, 4, 2, 'NM-HOME-003', 'Grove Storage Basket Set', 'grove-storage-basket-set', 'Woven storage baskets sized for shelves, consoles, and entryways.', 'Grove Storage Basket Set helps tidy everyday clutter while keeping the room looking relaxed and polished.', 44.00, 54.00, 22, 'https://storage.googleapis.com/novamarket-product-images/product-images/hearth-throw-blanket-3.jpg', 0.00, 0, 1, 0, '2026-02-25 11:40:00'),
    (24, 2, 1, 'NM-TECH-003', 'AirLite Mini Fan', 'airlite-mini-fan', 'Rechargeable mini fan for bedside tables, desks, and travel bags.', 'AirLite Mini Fan delivers a quiet airflow boost with a foldable stand and USB-C charging.', 35.00, 45.00, 31, 'https://storage.googleapis.com/novamarket-product-images/product-images/nova-wireless-earbuds-2.jpg', 0.00, 0, 1, 0, '2026-02-26 15:05:00'),
    (25, 6, 3, 'NM-KITCHEN-005', 'Cedar Knife Set', 'cedar-knife-set', 'Three-piece prep knife set with slim edge guards.', 'Cedar Knife Set covers the daily chopping essentials with balanced handles and compact storage sleeves.', 94.00, 119.00, 15, 'https://storage.googleapis.com/novamarket-product-images/product-images/aeroblend-portable-blender-3.jpg', 0.00, 0, 1, 0, '2026-02-27 13:55:00'),
    (26, 8, 7, 'NM-TRAVEL-003', 'Atlas Packing Cube Set', 'atlas-packing-cube-set', 'Compression packing cubes sized for carry-on and weekender bags.', 'Atlas Packing Cube Set keeps layers and accessories sorted across short business trips or long weekends away.', 39.00, 49.00, 28, 'https://storage.googleapis.com/novamarket-product-images/product-images/tidefold-weekender-bag-3.jpg', 0.00, 0, 1, 0, '2026-02-28 10:10:00'),
    (27, 5, 5, 'NM-LIFE-003', 'Shoreline Key Organizer', 'shoreline-key-organizer', 'Compact key wrap that keeps metal edges quiet inside your bag.', 'Shoreline Key Organizer cleans up your pocket carry with an easy screw-lock bar and slim profile.', 24.00, 30.00, 42, 'https://storage.googleapis.com/novamarket-product-images/product-images/terra-recycled-tote-3.jpg', 0.00, 0, 1, 0, '2026-03-01 08:25:00'),
    (28, 7, 4, 'NM-WELL-005', 'Focus Noise Machine', 'focus-noise-machine', 'Portable sound machine with sleep, calm, and focus presets.', 'Focus Noise Machine creates a steady background sound for work blocks, naps, and shared rooms.', 62.00, 78.00, 16, 'https://storage.googleapis.com/novamarket-product-images/product-images/pulse-smart-bottle-3.jpg', 0.00, 0, 1, 0, '2026-03-02 16:45:00'),
    (29, 3, 6, 'NM-DESK-006', 'Glow Desk Clock', 'glow-desk-clock', 'Soft-lit desk clock with silent operation and easy brightness controls.', 'Glow Desk Clock keeps time visible without overpowering the room, making it ideal for desks and bedside tables.', 45.00, 58.00, 23, 'https://storage.googleapis.com/novamarket-product-images/product-images/halo-standing-desk-lamp.jpg', 0.00, 0, 1, 0, '2026-03-03 12:35:00'),
    (30, 4, 2, 'NM-HOME-004', 'Cove Soy Candle Trio', 'cove-soy-candle-trio', 'Three clean-burning soy candles for layered home fragrance.', 'Cove Soy Candle Trio blends soft scent notes with reusable glass jars that feel right at home on a shelf or tray.', 38.00, 48.00, 30, 'https://storage.googleapis.com/novamarket-product-images/product-images/solace-aroma-diffuser.jpg', 0.00, 0, 1, 0, '2026-03-04 14:15:00'),
    (31, 2, 1, 'NM-TECH-004', 'RapidCharge Power Bank', 'rapidcharge-power-bank', 'High-capacity power bank with dual-device charging.', 'RapidCharge Power Bank keeps phones and smaller devices powered through commute days, flights, and long meetings.', 69.00, 85.00, 20, 'https://storage.googleapis.com/novamarket-product-images/product-images/nova-wireless-earbuds-3.jpg', 0.00, 0, 1, 1, '2026-03-05 10:55:00'),
    (32, 8, 7, 'NM-TRAVEL-004', 'Traveler Passport Wallet', 'traveler-passport-wallet', 'Zip wallet with slots for passport, cards, and boarding passes.', 'Traveler Passport Wallet keeps travel documents protected and accessible with a slim, easy-to-pack silhouette.', 33.00, 44.00, 26, 'https://storage.googleapis.com/novamarket-product-images/product-images/tidefold-weekender-bag.jpg', 0.00, 0, 1, 0, '2026-03-06 09:05:00');
