INSERT INTO chat_messages (id, conversation_id, sender_id, body, created_at) VALUES
    (1, 1, 9, 'Hi, does the earbud case support USB-C charging?', '2026-03-28 08:40:00'),
    (2, 1, 2, 'Yes, it charges by USB-C and usually reaches full charge in about 90 minutes.', '2026-03-28 09:05:00'),
    (3, 1, 9, 'Great, thank you. That helps a lot.', '2026-03-28 09:12:00'),
    (4, 2, 10, 'Is the throw blanket closer to cream or light beige?', '2026-03-24 12:20:00'),
    (5, 2, 4, 'It reads as a warm light beige in daylight and slightly cream indoors.', '2026-03-24 13:10:00'),
    (6, 3, 12, 'Can I use the diffuser with thicker essential oil blends?', '2026-03-26 16:00:00'),
    (7, 3, 7, 'Yes, but we recommend a lighter ratio and regular cleaning if the blend is dense.', '2026-03-26 16:25:00'),
    (8, 3, 12, 'Perfect. I will try that.', '2026-03-26 16:33:00'),
    (9, 4, 15, 'Would the tote fit a 13-inch laptop plus a bottle?', '2026-03-29 10:10:00'),
    (10, 4, 5, 'Yes, it fits a 13-inch laptop sleeve and has a separate bottle pocket inside.', '2026-03-29 10:28:00'),
    (11, 5, 21, 'Can the power bank charge a tablet and phone at the same time?', '2026-04-01 08:10:00'),
    (12, 5, 2, 'Yes, dual charging works well for a phone and tablet, though it drains the battery faster.', '2026-04-01 08:35:00'),
    (13, 5, 21, 'Thanks, that is exactly what I needed to know.', '2026-04-01 08:40:00'),
    (14, 6, 24, 'Is the passport wallet made from a matte or glossy finish?', '2026-03-31 17:00:00'),
    (15, 6, 8, 'It has a matte coated finish with a soft grain texture on the outside.', '2026-03-31 17:20:00');
